/** The Hengout mark: the app icon (an H wrapped in a speech bubble), generated by scripts/images.mjs. */
export function Mark({ size = 24 }: { size?: number }) {
  // eslint-disable-next-line @next/next/no-img-element
  return <img src="/img/mark-96.png" width={size} height={size} alt="" aria-hidden="true" decoding="async" style={{ display: 'block', borderRadius: size * 0.225 }} />;
}
